options.styles:
.u{border:1px solid rgba(128,128,128,.28);border-radius:12px;padding:14px 16px;margin:0 0 12px;background:rgba(128,128,128,.07)}
.u.wn{border:2px solid #F2A900}
.hd{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:12px}
.nm{font-size:20px;font-weight:600;text-transform:lowercase}
.pill{display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:600;padding:4px 12px;border-radius:8px}
.pill i{font-size:18px}
.pill.ok{background:rgba(46,158,91,.22);color:#4fd18a}
.pill.wn{background:rgba(242,169,0,.22);color:#F2A900}
.pill.na{background:rgba(128,128,128,.2)}
.rd{margin-left:auto;display:flex;gap:22px;font-size:13px;opacity:.95;white-space:nowrap}
.rd b{font-size:22px;font-weight:600;margin-left:4px}
.rd .wn b{color:#F2A900}
.g{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.t{border-radius:8px;padding:12px 6px 10px;text-align:center;border:1px solid rgba(128,128,128,.25)}
.t i{font-size:34px;display:block;margin-bottom:6px}
.t .l{font-size:13px}
.t .v{font-size:16px;font-weight:600}
.t.on{background:rgba(46,158,91,.22);color:#4fd18a;border-color:rgba(46,158,91,.6)}
.t.off,.t.na{background:rgba(128,128,128,.12);color:rgba(150,150,150,.9)}
.short{display:none}
@media (max-width:600px){
.u{padding:10px 10px;margin-bottom:10px}
.hd{gap:8px;margin-bottom:8px}
.nm{font-size:18px}
.pill{font-size:13px;padding:3px 9px}
.rd{margin-left:0;width:100%;justify-content:space-between;gap:8px;font-size:12px}
.rd b{font-size:18px}
.g{gap:6px}
.t{padding:8px 2px 6px}
.t i{font-size:26px;margin-bottom:3px}
.t .l{font-size:11px}
.t .v{font-size:13px}
.full{display:none}
.short{display:inline}
}

/* Variante para TV: tarjetas compactas una al lado de otra. Cada testigo es solo
   el icono y el color (verde = encendido, gris = apagado), sin texto ni porcentaje. */
&{flex-direction:row !important;gap:12px;align-items:stretch}
.dt-row{flex:1 1 0;min-width:0;display:flex;align-self:stretch !important;height:auto !important}
.u{box-sizing:border-box;flex:1;margin:0;padding:12px 16px}
.hd{margin-bottom:10px;gap:10px}
.nm{font-size:28px}
.pill{font-size:16px;padding:4px 12px}
.rd{font-size:15px;gap:20px;margin-left:0;width:100%;justify-content:space-between}
.rd b{font-size:26px}
.g{gap:8px}
.t{padding:10px 6px}
.t i{font-size:40px;margin:0}
.t .l,.t .v{display:none}

